<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {getKnowledgeOverview} from '../services/knowledge.ts'
import {checkBatch,importBatch,previewBatch,publishBatch} from '../services/graph-admin.ts'
import type {GraphBatch,GraphDraft} from '../services/graph-admin.ts'
const route=useRoute(),batchId=ref(String(route.query.batch_id??'')),source=ref(''),revision=ref(''),draft=ref<GraphDraft|null>(null),batch=ref<GraphBatch|null>(null),busy=ref(false),error=ref(''),notice=ref('')
const publishMode=computed(()=>route.path.endsWith('/publish'))
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败；请核对当前批次后重试。'}finally{busy.value=false}}
async function readB(){await action(async()=>{draft.value=null;const b=await getKnowledgeOverview();source.value=b.dataset_id;revision.value=b.snapshot_revision;notice.value=`B 当前已确认实体 ${b.review_counts.confirmed.entities}、关系 ${b.review_counts.confirmed.relations}。不会自动确认或发布。`})}
async function preview(){await action(async()=>{draft.value=null;draft.value=await previewBatch(batchId.value.trim(),source.value.trim(),revision.value)})}
async function ingest(){if(!draft.value)return;await action(async()=>{const result=await importBatch(draft.value!);notice.value=result.replay?'相同内容已存在，未重复导入。':'已导入 C，尚未发布。';batch.value=await checkBatch(batchId.value.trim())})}
async function check(){await action(async()=>{batch.value=null;batch.value=await checkBatch(batchId.value.trim())})}
async function publish(){if(!batch.value)return;await action(async()=>{const result=await publishBatch(batch.value!.id,batch.value!.active_batch_id);notice.value=`已发布 ${result.batch_id}，上个版本 ${result.previous_batch_id??'无'}。`;batch.value=await checkBatch(result.batch_id)})}
watch([batchId,source],()=>{draft.value=null;batch.value=null})
watch(()=>route.query.batch_id,()=>{batchId.value=String(route.query.batch_id??'');if(batchId.value)void check()})
onMounted(async()=>{if(publishMode.value){if(batchId.value)await check()}else await readB()})
</script>
<template><section class="standard-page"><div class="page-heading"><div><h1>{{publishMode?'发布已校验批次':'图谱批次生成与校验'}}</h1><p>B 审核、C 导入与发布相互独立；只接受 reviewed_export，不启用开发夹具。</p></div></div><p v-if="notice" class="inline-success" role="status">{{notice}}</p><p v-if="error" class="inline-error" role="alert">{{error}}</p><section class="panel batch-card"><label>批次号<input v-model="batchId" class="form-input" maxlength="80" :disabled="busy" placeholder="为新的完整快照填写唯一批次号"/></label><div v-if="!publishMode"><label>来源样本集标识<input v-model="source" class="form-input" maxlength="200" :disabled="busy"/></label><p class="small-note">默认来自 B 的 dataset_id，不冒充 A 的数据库导入任务号。</p><div class="batch-buttons"><button class="button button-secondary" :disabled="busy" @click="readB">重新读取 B 审核结果</button><button class="button button-secondary" :disabled="busy||!batchId||!revision||!source" @click="preview">生成批次预览</button></div><template v-if="draft"><dl class="definition-list"><dt>来源</dt><dd>{{draft.provenance}}</dd><dt>论文</dt><dd>{{draft.paper_count}}</dd><dt>实体 / 关系</dt><dd>{{draft.entity_count}} / {{draft.relation_count}}</dd><dt>词表</dt><dd>{{draft.vocabulary_version}}</dd><dt>内容指纹</dt><dd class="mono">{{draft.digest}}</dd></dl><button class="button button-primary" :disabled="busy" @click="ingest">导入此快照到 C（不发布）</button></template></div><div class="batch-buttons"><button class="button button-secondary" :disabled="busy||!batchId" @click="check">读取批次并校验</button><RouterLink v-if="batchId&&!publishMode" :to="{path:'/admin/graph/batches/publish',query:{batch_id:batchId}}" class="text-button">前往发布确认</RouterLink></div></section><section v-if="batch" class="panel batch-card"><h2>批次 {{batch.id}}</h2><dl class="definition-list"><dt>状态</dt><dd>{{batch.status}}</dd><dt>来源</dt><dd>{{batch.provenance}}</dd><dt>实体 / 关系</dt><dd>{{batch.entity_count}} / {{batch.relation_count}}</dd><dt>当前发布</dt><dd>{{batch.active_batch_id??'尚无发布'}}</dd></dl><p v-for="(ok,key) in batch.checks" :key="key">{{key}}：{{ok?'通过':'未通过'}}</p><template v-if="publishMode"><p class="small-note">发布会把研究入口从 {{batch.active_batch_id??'无'}} 切换到 {{batch.id}}。已打开页面仍可固定旧批次；发布只代表当前结构/计数门槛通过，不代表准确率评估达标。</p><button class="button button-primary" :disabled="busy||!batch.publishable||batch.provenance!=='reviewed_export'" @click="publish">发布此批次</button></template><RouterLink v-if="batch.status==='published'&&batch.provenance==='reviewed_export'" :to="{path:'/research/papers',query:{batch_id:batch.id}}" class="text-button">查看此发布批次</RouterLink></section></section></template>
<style scoped>.batch-card{padding:24px;margin:20px 0}.batch-card label{display:block;font-size:12px;margin:15px 0}.batch-card .form-input{margin-top:8px;max-width:650px}.batch-buttons{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin:20px 0}.batch-card>p{font-size:12px;line-height:1.8;margin:12px 0}.batch-card>.button{margin:15px 20px 15px 0}.batch-card .mono{overflow-wrap:anywhere}</style>
